@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  html {
    @apply font-sans;
  }
}

.font-alan {
  font-family: var(--font-alan), sans-serif;
}

.font-mono {
  font-family: var(--font-mono), monospace;
}

.font-playfair {
  font-family: var(--font-playfair), serif;
}

.font-chango {
  font-family: var(--font-chango), cursive;
}

/* ─── Base Reset ──────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
}
.root {
  isolation: isolate;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  scroll-behavior: auto; /* Lenis handles this */
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-alan), system-ui, -apple-system, sans-serif;
}

/* ─── Scrollbar ───────────────────────────────────────────── */
.scrollbar-hide {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.scrollbar-hide::-webkit-scrollbar {
  display: none;
}

/* ─── Glass surface ───────────────────────────────────────── */
.glass {
  background: rgba(13, 17, 23, 0.6);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

/* ─── Glow utilities ──────────────────────────────────────── */
.glow-cyan {
  box-shadow:
    0 0 0 1px rgba(6, 182, 212, 0.15),
    0 0 24px rgba(6, 182, 212, 0.12),
    0 0 48px rgba(6, 182, 212, 0.06);
}
.glow-purple {
  box-shadow:
    0 0 0 1px rgba(168, 85, 247, 0.15),
    0 0 24px rgba(168, 85, 247, 0.12),
    0 0 48px rgba(168, 85, 247, 0.06);
}
.glow-green {
  box-shadow:
    0 0 0 1px rgba(34, 197, 94, 0.15),
    0 0 24px rgba(34, 197, 94, 0.12),
    0 0 48px rgba(34, 197, 94, 0.06);
}
.glow-cyan-sm {
  box-shadow: 0 0 16px rgba(6, 182, 212, 0.35);
}

/* ─── Shimmer text ────────────────────────────────────────── */
.shimmer-text {
  background: linear-gradient(
    90deg,
    #06b6d4 0%,
    #a855f7 35%,
    #06b6d4 65%,
    #a855f7 100%
  );
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer 4s linear infinite;
}

/* ─── Shimmer code glow ───────────────────────────────────── */
.shimmer-code {
  position: relative;
}
.shimmer-code::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    transparent 30%,
    rgba(6, 182, 212, 0.04) 50%,
    transparent 70%
  );
  background-size: 200% 100%;
  animation: shimmer 3s linear infinite;
  pointer-events: none;
}

/* ─── Syntax token colors ─────────────────────────────────── */
.token-keyword  { color: #ff7b72; }
.token-function { color: #d2a8ff; }
.token-string   { color: #a5d6ff; }
.token-number   { color: #79c0ff; }
.token-comment  { color: #8b949e; font-style: italic; }
.token-variable { color: #ffa657; }
.token-operator { color: #ff7b72; }
.token-punct    { color: #c9d1d9; }

/* ─── Keyframes ───────────────────────────────────────────── */
@keyframes shimmer {
  0%   { background-position: -200% center; }
  100% { background-position:  200% center; }
}

@keyframes cursor-blink {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0; }
}

@keyframes glow-pulse {
  0%, 100% { box-shadow: 0 0 20px rgba(6,182,212,0.25), 0 0 40px rgba(6,182,212,0.10); }
  50%       { box-shadow: 0 0 32px rgba(6,182,212,0.45), 0 0 64px rgba(6,182,212,0.20); }
}

/* ─── Tailwind custom utilities ───────────────────────────── */
@layer utilities {
  .animate-cursor-blink { animation: cursor-blink 1s step-end infinite; }
  .animate-glow-pulse   { animation: glow-pulse 2.4s ease-in-out infinite; }

}

/* Minimal premium scrollbar */
.scrollbar-thin {
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.15) transparent;
}

/* Chrome / Edge / Safari */
.scrollbar-thin::-webkit-scrollbar {
  width: 6px;
}

.scrollbar-thin::-webkit-scrollbar-track {
  background: transparent;
}
.scrollbar-thin::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.12);
  border-radius: 999px;
  transition: background 0.2s ease;
}

/* Hover = more visible */
.scrollbar-thin:hover::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.28);
}

/* Active drag */
.scrollbar-thin::-webkit-scrollbar-thumb:active {
  background: rgba(255,255,255,0.45);
}

/* ─── Accessibility ───────────────────────────────────────── */
:root {
  --focus-ring: var(--accent);
}

/* Zero specificity and inside a layer, so any component's own outline-none / ring wins.
   Monaco manages its own focus. */
@layer base {
  :where(
      a[href],
      button,
      summary,
      input,
      select,
      textarea,
      [tabindex]:not([tabindex="-1"]),
      [role="button"],
      [role="menuitem"],
      [role="switch"],
      [role="separator"]
    ):where(:not(.monaco-editor *)):focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
  }
}

/* Reduced motion: stops CSS animations and transitions site-wide. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

