      <motion.div
        ref={ref}
        className={cn(
          "relative overflow-hidden rounded-2xl",
          "border border-white/[0.08]",
          "shadow-[0_0_0_1px_rgba(255,255,255,0.04),0_32px_80px_rgba(0,0,0,0.8),0_0_60px_rgba(99,102,241,0.05)]",
          className
        )}
        style={{
