export function GoogleLoginModal({
    isOpen,
    onClose,
    onGoogleLogin,
}: GoogleLoginModalProps) {
    const { cardRef, logoRef, contentRef } = useModalAnimations(isOpen);
    const isClient = useIsClient();

    useEffect(() => {
        document.body.style.overflow = isOpen ? "hidden" : "";
