                                <div
                                    ref={logoRef}
                                    className="mb-8 flex flex-col items-center"
                                >
                                    <div className="relative mb-4">
                                        {/* Orange pulse rings */}
                                        {[0, 0.55].map((delay, i) => (
                                            <motion.div
                                                key={i}
                                                className="absolute inset-0 rounded-2xl"
                                                style={{
