/* filepath: src/components/CodeEditor/CodeEditor.module.css */

/* ─── Design Tokens ──────────────────────────────────────────────── */
.container {
    /* 60% primary background */
    --bg: #1e1e1e;
    --bg-raised: #252525;
    --bg-highlight: #2d2d2d;

    /* 10% cream text */
    --cream: #f0ead6;
    --cream-60: rgba(240, 234, 214, 0.6);
    --cream-35: rgba(240, 234, 214, 0.35);
    --cream-15: rgba(240, 234, 214, 0.15);
    --cream-08: rgba(240, 234, 214, 0.08);

    /* 10% orange accent */
    --orange: #ff5800;
    --orange-40: rgba(255, 88, 0, 0.4);
    --orange-22: rgba(255, 88, 0, 0.22);
    --orange-14: rgba(255, 88, 0, 0.14);
    --orange-08: rgba(255, 88, 0, 0.08);

    /* 20% Dracula syntax palette — used for UI chrome accents */
    --pink: #ff79c6;
    --green: #50fa7b;
    --yellow: #f1fa8c;
    --purple: #bd93f9;
    --cyan: #8be9fd;
    --orange-syn: #ffb86c;
    --comment: #6272a4;
    --red: #ff5555;

    /* Geometry */
    --r-xl: 14px;
    --r-lg: 10px;
    --r-md: 7px;
    --r-sm: 5px;

    /* Layout */
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    min-height: 0; /* critical: lets flex children shrink below content size */
}

/* ─── Ambient Glow Orbs ──────────────────────────────────────────── */
.glowOrb1,
.glowOrb2 {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    z-index: 0;
    will-change: transform;
}

.glowOrb1 {
    width: 320px;
    height: 320px;
    top: -80px;
    right: -60px;
    background: radial-gradient(
        circle,
        rgba(255, 88, 0, 0.1) 0%,
        transparent 70%
    );
    filter: blur(50px);
}

.glowOrb2 {
    width: 220px;
    height: 220px;
    bottom: -50px;
    left: -40px;
    background: radial-gradient(
        circle,
        rgba(189, 147, 249, 0.08) 0%,
        transparent 70%
    );
    filter: blur(44px);
}

/* ─── Editor Frame ───────────────────────────────────────────────── */
.editorFrame {
    position: relative;
    z-index: 1;
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;

    background: var(--bg);
    border: 1px solid var(--cream-35);
    border-radius: var(--r-xl);
    overflow: hidden;

    box-shadow:
        0 0 0 1px var(--orange-08),
        0 8px 40px rgba(0, 0, 0, 0.55),
        0 1px 0 var(--cream-08) inset,
        0 0 60px rgba(255, 88, 0, 0.03) inset;

    transition:
        border-color 0.3s ease,
        box-shadow 0.3s ease;
}

.editorFrame:focus-within {
    box-shadow:
        0 0 0 1px var(--orange-14),
        0 8px 40px rgba(0, 0, 0, 0.55),
        0 1px 0 var(--cream-08) inset,
        0 0 80px rgba(255, 88, 0, 0.06) inset;
}

/* ─── Window Chrome ──────────────────────────────────────────────── */
.windowChrome {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 11px 16px 9px;
    background: var(--bg-raised);
    border-bottom: 1px solid var(--cream-08);
    flex-shrink: 0;
    user-select: none;
}

.chromeDot {
    width: 11px;
    height: 11px;
    border-radius: 50%;
    cursor: default;
    transition:
        filter 0.2s ease,
        transform 0.15s ease;
}
.chromeDot:hover {
    filter: brightness(1.15);
    transform: scale(1.1);
}

.chromeDotRed {
    background: #ff5f57;
    box-shadow: 0 0 5px rgba(255, 95, 87, 0.45);
}
.chromeDotYellow {
    background: #ffbd2e;
    box-shadow: 0 0 5px rgba(255, 189, 46, 0.45);
}
.chromeDotGreen {
    background: #28c840;
    box-shadow: 0 0 5px rgba(40, 200, 64, 0.45);
}

.chromeTitle {
    margin-left: 10px;
    font-size: 11.5px;
    color: var(--cream-60);
    font-family: var(--font-mono);
