}

/* ─── Toolbar ────────────────────────────────────────────────────── */
.toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 7px 12px;
    background: var(--bg-raised);
    border-bottom: 1px solid var(--cream-08);
    gap: 8px;
    flex-shrink: 0;
}

.toolbarLeft,
.toolbarRight {
    display: flex;
    align-items: center;
    gap: 7px;
}

/* Language dropdown */
.languageSelector {
    position: relative;
    display: flex;
    align-items: center;
    gap: 6px;
    background: var(--bg-highlight);
    border: 1px solid var(--cream-15);
    border-radius: var(--r-md);
    padding: 4px 8px;
    transition: border-color 0.2s ease;
}
.languageSelector:focus-within {
    border-color: var(--orange-40);
}

.langIcon {
    display: flex;
    align-items: center;
    flex-shrink: 0;
}

.langSelect {
    background: transparent;
    border: none;
    color: var(--cream-60);
    font-size: 12px;
    font-family: inherit;
    outline: none;
    cursor: pointer;
    padding-right: 16px;
    appearance: none;
    -webkit-appearance: none;
}
.langSelect option {
    background: var(--bg-highlight);
    color: var(--cream);
}

.selectChevron {
    position: absolute;
    right: 7px;
    display: flex;
    align-items: center;
    color: var(--cream-35);
    pointer-events: none;
}

/* ─── Language Pills ─────────────────────────────────────────────── */
.langPills {
    display: flex;
    gap: 3px;
}

.langPill {
    position: relative; /* anchors the layoutId background */
    overflow: hidden;
    display: flex;
    align-items: center;
    padding: 4px 10px;
    border-radius: var(--r-md);
    background: transparent;
    border: 1px solid transparent;
    color: var(--cream-60);
    font-size: 12px;
    font-family: inherit;
    cursor: pointer;
    white-space: nowrap;
    transition: color 0.18s ease;
}
.langPill:disabled {
    opacity: 0.38;
    cursor: not-allowed;
}
.langPill:hover:not(:disabled) {
    color: var(--cream-60);
}

/* Active pill: only drives color; the motion.div handles the bg */
.langPillActive {
    color: var(--cream) !important;
}

/* The framer-motion layoutId background for the active pill */
.langPillBg {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    border: 1px solid var(--cream-35);
    /* box-shadow: 0 0 14px var(--orange-08); */
}

/* Content layer sits above the animated background */
.langPillContent {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    gap: 5px;
}

/* ─── Icon Buttons ───────────────────────────────────────────────── */
.iconBtn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border-radius: var(--r-md);
    background: transparent;
    border: 1px solid var(--cream-15);
    color: var(--cream-60);
    cursor: pointer;
    overflow: hidden;
    transition:
        color 0.18s ease,
        border-color 0.18s ease,
        background 0.18s ease;
}
.iconBtn:hover:not(:disabled) {
    color: var(--cream);
    background: var(--orange-08);
    border-color: var(--orange-22);
}
.iconBtn:disabled {
    opacity: 0.32;
    cursor: not-allowed;
}

.iconBtnSuccess {
    color: var(--green) !important;
    border-color: rgba(80, 250, 123, 0.38) !important;
    background: rgba(80, 250, 123, 0.07) !important;
