        opacity: 0.35;
    }
}

/* ─── Editor Wrapper ─────────────────────────────────────────────── */
.editorWrapper {
    flex: 1; /* fills remaining space in the flex column */
    min-height: 0; /* allows shrinking below content height */
    position: relative;
    overflow: hidden;
}

/* ─── Status Bar ─────────────────────────────────────────────────── */
.statusBar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 5px 14px;
    background: var(--bg-raised);
    border-top: 1px solid var(--cream-08);
    flex-shrink: 0;
}

.statusBarLeft,
.statusBarRight {
    display: flex;
    align-items: center;
    gap: 6px;
}

.statusItem {
    font-size: 11px;
    color: var(--cream-60);
    font-family: var(--font-mono);
    letter-spacing: 0.3px;
}

.statusDivider {
    color: var(--cream-15);
    font-size: 10px;
}

.statusReadOnly {
    font-size: 11px;
    font-family: var(--font-mono);
    letter-spacing: 0.6px;
    color: var(--purple);
}

.statusEditable {
    font-size: 11px;
    font-family: var(--font-mono);
    letter-spacing: 0.6px;
    color: var(--green);
}

/* ─── Loading Skeleton ───────────────────────────────────────────── */
.editorSkeleton {
    display: flex;
    flex-direction: column;
    gap: 13px;
    padding: 22px 20px;
    height: 100%;
    background: var(--bg);
}

.skeletonLine {
    height: 13px;
    border-radius: var(--r-sm);
    background: linear-gradient(90deg, #2a2a2a 25%, #333333 50%, #2a2a2a 75%);
    background-size: 200% 100%;
    animation: shimmer 1.5s ease-in-out infinite;
}

@keyframes shimmer {
    0% {
        background-position: 200% 0;
    }
    100% {
        background-position: -200% 0;
    }
}

/* ─── Screen-reader only ─────────────────────────────────────────── */
.srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

