    <rect width="16" height="16" rx="3" fill="#3776AB" />
    <text x="3" y="13" fontSize="9" fontWeight="700" fill="#FFD43B" fontFamily="monospace">
      Py
    </text>
  </svg>
);

const FormatIcon: React.FC = () => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d="M21 10H7M16 6H3M21 14H7M16 18H3" />
  </svg>
);

const SpinnerIcon: React.FC = () => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
    <path d="M21 12a9 9 0 1 1-6.219-8.56" strokeLinecap="round" />
  </svg>
);

const ReadOnlyIcon: React.FC = () => (
  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <rect width="18" height="11" x="3" y="11" rx="2" ry="2" />
    <path d="M7 11V7a5 5 0 0 1 10 0v4" />
  </svg>
);

const CopyIcon: React.FC = () => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <rect width="14" height="14" x="8" y="8" rx="2" ry="2" />
    <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" />
  </svg>
);

const CheckIcon: React.FC = () => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d="M20 6L9 17l-5-5" />
  </svg>
);

const LANGUAGE_OPTIONS: Language[] = ['javascript', 'python'];

export const EditorToolbar: React.FC<EditorToolbarProps> = ({
  language,
  onLanguageChange,
  onFormat,
  onCopy,
  isFormatting,
  isCopied,
  readOnly,
  isReady,
}) => {
  const selectId = useId();

  return (
    <div className={styles.toolbar} role="toolbar" aria-label="Editor toolbar">
      {/* Left: Language selector */}
      <div className={styles.toolbarLeft}>
        <div className={styles.languageSelector}>
          <label htmlFor={selectId} className={styles.srOnly}>
            Select language
          </label>
          <div className={styles.langIcon} aria-hidden>
            {language === 'javascript' ? <JSIcon /> : <PyIcon />}
          </div>
          <select
            id={selectId}
            value={language}
            onChange={(e) => onLanguageChange(e.target.value as Language)}
            className={styles.langSelect}
            disabled={!isReady}
            aria-label="Programming language"
          >
            {LANGUAGE_OPTIONS.map((lang) => (
              <option key={lang} value={lang}>
                {LANGUAGE_LABELS[lang]}
              </option>
            ))}
          </select>
          <div className={styles.selectChevron} aria-hidden>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
              <path d="M6 9l6 6 6-6" />
            </svg>
          </div>
        </div>

        {/* Language badge pills */}
        <div className={styles.langPills} role="group" aria-label="Language switcher">
          {LANGUAGE_OPTIONS.map((lang) => (
            <button
              key={lang}
              type="button"
              className={`${styles.langPill} ${language === lang ? styles.langPillActive : ''}`}
              onClick={() => onLanguageChange(lang)}
              disabled={!isReady}
              aria-pressed={language === lang}
            >
              {lang === 'javascript' ? <JSIcon /> : <PyIcon />}
              <span>{LANGUAGE_LABELS[lang]}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Right: Actions */}
      <div className={styles.toolbarRight}>
        {readOnly && (
          <div className={styles.readOnlyBadge} aria-label="Read-only mode">
            <ReadOnlyIcon />
            <span>Read-only</span>
          </div>
        )}

        {/* Copy button — always visible */}
        <button
          type="button"
          className={`${styles.iconBtn} text-foreground ${isCopied ? styles.iconBtnSuccess : ''}`}
          onClick={onCopy}
          disabled={!isReady}
          title="Copy code"
          aria-label={isCopied ? 'Copied!' : 'Copy code'}
        >
          {isCopied ? <CheckIcon /> : <CopyIcon />}
        </button>

        {/* Format button — hidden in readOnly mode */}
        {!readOnly && (
          <button
            type="button"
            className={`${styles.iconBtn} ${isFormatting ? styles.iconBtnLoading : ''}`}
            onClick={onFormat}
            disabled={!isReady || isFormatting}
            title="Format code (Alt+Shift+F)"
            aria-label="Format code"
          >
            {isFormatting ? (
              <span className={styles.spinnerWrapper}><SpinnerIcon /></span>
            ) : (
              <FormatIcon />
            )}
          </button>
        )}

        {/* LSP status dot */}
        <div
          className={`${styles.statusDot} ${isReady ? styles.statusDotReady : styles.statusDotLoading}`}
          title={isReady ? 'Editor ready' : 'Loading editor…'}
          role="status"
          aria-label={isReady ? 'Editor ready' : 'Loading editor'}
        />
      </div>
    </div>
  );
};

