"use client";
import { motion } from "motion/react";

interface LoaderOneProps {
    /** dot diameter in px */
    size?: number;
    className?: string;
}

export const LoaderOne = ({ size = 6, className = "" }: LoaderOneProps) => {
    const bounce = Math.max(3, Math.round(size * 0.7));

    return (
        <div
            role="status"
            aria-label="Loading"
            className={`flex items-center gap-1 text-current ${className}`}
        >
            {[0, 1, 2].map((i) => (
                <motion.span
                    key={i}
                    initial={{ y: 0, opacity: 0.4 }}
                    animate={{ y: [0, -bounce, 0], opacity: [0.4, 1, 0.4] }}
                    transition={{
                        duration: 0.9,
                        repeat: Infinity,
                        repeatType: "loop",
                        delay: i * 0.15,
                        ease: "easeInOut",
                    }}
                    style={{ width: size, height: size }}
                    className="block rounded-full bg-current"
                />
            ))}
        </div>
    );
};

export const LoaderTwo = () => {
  const transition = (x: number) => {
    return {
      duration: 2,
      repeat: Infinity,
      repeatType: "loop" as const,
      delay: x * 0.2,
      ease: "easeInOut" as const,
    };
