FILE=components/visualizers/hash/hashing.ts
mkdir -p "$(dirname "$V/$FILE")"
cat > "$V/$FILE" <<'__VISUALIZER_FILE_120_EOF__'
import type { Primitive } from "./types";

/**
 * Hashing rules (deterministic, no randomness, no per-session seed):
 *
 * 1. CANONICALIZE  Every value is turned into a type-tagged string first:
 *      "apple" -> "s:apple"    1 -> "n:1"    "1" -> "s:1"
 *      true    -> "b:true"     null -> "z:null"
 *    The tag keeps 1 and "1" (and true and "true") apart, both in the hash
 *    and in equality.
 * 2. HASH          32-bit FNV-1a over the UTF-16 code units of that string:
 *      h = 0x811C9DC5;  for each unit u:  h ^= u;  h = (h * 0x01000193) mod 2^32
 * 3. BUCKET        bucket = hash mod capacity   (capacity is always a power of two)
 *
 * Equality is strict and type-aware (`===` on primitives), so 1 !== "1",
 * and 0 === -0 (their canonical forms are identical too).
 */

export const MAX_LOAD_FACTOR = 0.75;
export const DEFAULT_CAPACITY = 8;
export const CAPACITY_CHOICES = [4, 8, 16, 32] as const;
export const MAX_CAPACITY = 32;
/** 0.75 * MAX_CAPACITY, so a full table never needs more than MAX_CAPACITY buckets. */
export const MAX_ENTRIES = 24;

export type TypeName = "string" | "number" | "boolean" | "null";

export function typeName(v: Primitive): TypeName {
    return v === null ? "null" : (typeof v as TypeName);
}

export function canonical(v: Primitive): string {
    switch (typeName(v)) {
        case "string":
            return `s:${v as string}`;
        case "number":
            return `n:${Object.is(v, -0) ? "0" : String(v)}`;
        case "boolean":
            return `b:${String(v)}`;
        default:
            return "z:null";
    }
}

export function fnv1a(text: string): number {
    let h = 0x811c9dc5;
    for (let i = 0; i < text.length; i++) {
        h ^= text.charCodeAt(i);
        h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h >>> 0;
}

export const hashOf = (v: Primitive): number => fnv1a(canonical(v));
export const hex = (h: number): string =>
    `0x${h.toString(16).toUpperCase().padStart(8, "0")}`;
export const bucketIndex = (hash: number, capacity: number): number =>
    hash % capacity;
export const bucketOf = (v: Primitive, capacity: number): number =>
    bucketIndex(hashOf(v), capacity);

/** Strict, type-aware equality. */
export const keysEqual = (a: Primitive, b: Primitive): boolean => a === b;

export const loadFactor = (size: number, capacity: number): number =>
    capacity === 0 ? 0 : size / capacity;
/** Strictly greater than 0.75, so exactly 0.75 is still allowed. */
export const exceedsMaxLoad = (size: number, capacity: number): boolean =>
    size > capacity * MAX_LOAD_FACTOR;
export const fmtLoad = (size: number, capacity: number): string =>
    loadFactor(size, capacity).toFixed(3).replace(/0+$/, "").replace(/\.$/, ".0");

__VISUALIZER_FILE_120_EOF__

FILE=components/visualizers/hash/HashPipeline.tsx
mkdir -p "$(dirname "$V/$FILE")"
cat > "$V/$FILE" <<'__VISUALIZER_FILE_121_EOF__'
"use client";
import { fmt } from "./hashEngine";
import type { Trace } from "./types";

const ACCENT = "#FF430F";

function Token({
  value,
  label,
  color,
  attr,
}: {
  value: string;
  label: string;
  color?: string;
  attr?: Record<string, string>;
}) {
  return (
    <div {...attr} className="flex shrink-0 flex-col gap-1">
      <span
        className="max-w-[200px] truncate font-mono text-[13px] font-semibold leading-none"
        style={color ? { color } : undefined}
        title={value}
      >
        {value}
      </span>
      <span className="text-[11px] leading-none text-muted-foreground">{label}</span>
    </div>
  );
}

const Chevron = () => (
  <svg
    data-pipe-arrow
    width="12"
    height="12"
    viewBox="0 0 12 12"
    aria-hidden
    className="mb-3 shrink-0 text-muted-foreground/50"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M4 2.5 7.5 6 4 9.5" />
  </svg>
);

/**
 * One quiet line that reads like a formula:  input › text › hash › bucket › result.
 * Presentational only; the stage reveals the tokens left to right.
 */
export default function HashPipeline({ trace }: { trace: Trace | null }) {
  if (!trace)
    return (
      <p className="px-6 text-xs text-muted-foreground">
        Run an operation to watch a key become a hash, a bucket and a result.
      </p>
    );
  const miss = /not found|rejected/i.test(trace.outcome);
  const collision = /collision/i.test(trace.outcome);
  const result = miss ? "#E5484D" : collision ? "#D97706" : "#17A34A";
  const name = trace.label === "key" ? "key" : "value";

  return (
    <div className="px-6" aria-label="Hash pipeline" aria-live="polite">
      <div className="flex items-end gap-3 overflow-x-auto pb-3">
        <Token
          attr={{ "data-pipe": "" }}
          value={trace.pair !== undefined ? `${fmt(trace.subject)} → ${fmt(trace.pair)}` : fmt(trace.subject)}
          label={`${name} · ${trace.type}`}
        />
        <Chevron />
        <Token attr={{ "data-pipe": "" }} value={trace.canonical} label="type-tagged text" />
        <Chevron />
        <Token attr={{ "data-pipe": "" }} value={trace.hex} label={`hash · ${trace.hash}`} />
        <Chevron />
        <Token
          attr={{ "data-pipe": "" }}
          value={`${trace.hash} mod ${trace.capacity} = ${trace.bucket}`}
          label="bucket"
          color={ACCENT}
        />
        <Chevron />
        <Token attr={{ "data-pipe": "" }} value={trace.outcome} label="result" color={result} />
        {trace.resize && (
          <>
            <Chevron />
            <Token
              attr={{ "data-pipe-resize": "" }}
              value={`${trace.resize.from} → ${trace.resize.to} buckets`}
              label="resize and rehash"
              color="#D97706"
            />
          </>
        )}
      </div>
      <div aria-hidden className="relative h-px bg-primary-foreground/10">
        <span data-pipe-progress className="absolute inset-0 origin-left opacity-60" style={{ background: ACCENT }} />
      </div>
    </div>
  );
}

