import type { OpType } from "./types";

/** Conceptual costs, not measurements. */
export const COMPLEXITY: Record<OpType, string> = {
    initialize: "O(n): one node is created and linked per value.",
    reset: "O(n): rebuild the starter list.",
    append: "O(n) for a list that only stores HEAD (walk to the end); O(1) when TAIL is kept, as in this lab. Either way only a few pointers change.",
    prepend: "O(1): the new node points at the old head, and HEAD moves to it.",
    insertAt: "O(n): walk to the position first, then O(1) pointer changes.",
    insertAfter: "O(1) once you hold the node (finding it by id costs O(n)).",
    insertBefore: "O(1) in a doubly linked list (use prev); O(n) in a singly linked list, which must walk from HEAD to find the predecessor.",
    update: "O(n) to reach the index, then O(1) to overwrite the value.",
    read: "O(n): there is no random access; you follow next pointers from HEAD.",
    delete: "O(n) to reach the node, then O(1) pointer changes.",
    deleteHead: "O(1): HEAD moves to the next node.",
    deleteTail: "O(n) in a singly linked list (find the node before the tail); O(1) in a doubly linked list.",
    deleteById: "O(n) to find the node, then O(1) pointer changes.",
    findById: "O(n): follow next pointers until the id matches.",
    getLength: "O(1) if the length is stored, O(n) if it must be counted.",
    isEmpty: "O(1): is HEAD NULL?",
    reverse: "O(n): every pointer is redirected once.",
    clear: "O(n) to release the nodes (O(1) if you just drop HEAD).",
    swap: "O(n) to reach both positions, then O(1) pointer changes.",
    setType: "O(n): every node's pointers are rewritten for the new type.",
    highlight: "O(n) to reach the node; annotation only.",
    clearHighlights: "Annotation only.",
    mark: "O(n) to reach the index; a marker then stores the node id.",
    createMark: "O(n) to reach the index; a marker then stores the node id.",
    deleteMark: "O(1): drop the marker; the node is untouched.",
    readMark: "O(1) conceptually; this lab walks the list to find the index.",
    moveMarkToIndex: "O(n) to reach the index, then re-attach the marker.",
    moveMarkOne: "O(1): one next pointer step.",
    moveMarkBy: "O(k): k pointer steps.",
    moveMarkTo: "O(n): walk from HEAD to the index.",
    pointArrow: "Annotation only.",
    pointArrowFromTo: "Annotation only.",
    clearArrows: "Annotation only.",
};

