cat > "$V/$FILE" <<'__VISUALIZER_FILE_166_EOF__'
import type { OpType } from "./types";

const H = "O(h), where h is the tree's height. A balanced BST has h ≈ log n; a lopsided one can have h = n.";
const BIN = "In a plain binary tree";

/** Conceptual costs, not measurements. Binary tree and BST costs are kept apart on purpose. */
export const COMPLEXITY: Record<OpType, string> = {
    initialize: "O(n) for a Binary Tree. For a BST each value is inserted, so O(n·h).",
    reset: "O(n): rebuild the starter tree.",
    createRoot: "O(1): create one node.",
    insertNode: `O(1) once you hold the parent (finding it by id costs O(n)). ${BIN} you choose the position, so no search is needed.`,
    insertAtPath: "O(path length): follow one pointer per step, then O(1) to attach.",
    insert: `BST: ${H} The value decides at every node whether to go left or right.`,
    read: "O(1) if you hold the node; O(n) to find it by id without an index.",
    readAtPath: "O(path length): one pointer per step.",
    update: `O(1) to overwrite a value. In a BST the ordering must still hold, which is checked against the whole tree here (O(n)); a real BST only needs ${H.split(".")[0]}.`,
    setLeft: "O(1): change two pointers (child.parent and parent.child), plus a cycle check that walks up from the parent, O(h).",
    setRight: "O(1): change two pointers, plus a cycle check that walks up from the parent, O(h).",
    detach: "O(1): clear one pointer. The subtree itself is not touched.",
    deleteNode: `Binary Tree: O(1) once you hold the node. BST: ${H} (finding the in-order successor walks down the right subtree).`,
    deleteSubtree: "O(k) where k is the size of the subtree being removed.",
    getRoot: "O(1).",
    getParent: "O(1): the parent pointer is stored.",
    getLeft: "O(1): a stored pointer.",
    getRight: "O(1): a stored pointer.",
    getHeight: "O(k): every node below must be examined.",
    getDepth: "O(depth): follow parent pointers up to the root.",
    getDegree: "O(1): count two pointers.",
    getNodeCount: "O(1) if a counter is kept, O(n) if counted.",
    isEmpty: "O(1): is the root NULL?",
    clear: "O(n) to release the nodes (O(1) if you just drop the root).",
    swapChildren: "O(1): swap two pointers. The subtrees below do not change.",
    setType: "Binary → BST: O(n) to verify the ordering. BST → Binary: O(1), nothing to check.",
    highlight: "O(1) once you hold the node; annotation only.",
    clearHighlights: "Annotation only.",
    mark: "O(1) once you hold the node; a marker stores the node id.",
    createMark: "O(1) once you hold the node; a marker stores the node id.",
    deleteMark: "O(1): drop the marker; the node is untouched.",
    readMark: "O(1): the marker stores the node id.",
    moveMarkTo: "O(1): re-attach the marker.",
    moveMarkToIndex: "O(1): re-attach the marker.",
    pointArrow: "Annotation only.",
    pointArrowFromTo: "Annotation only.",
    clearArrows: "Annotation only.",
};

